import{_ as n,a0 as o,w as p,s as r,ao as d,I as l,x as i,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何在 Kali Linux 上安装 SSH 服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kali Linux 上安装 SSH 服务 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kali Linux 上安装 SSH 服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kali Linux 上安装 SSH 服务 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170121 How to install SSH  secure shell  service on Kali Linux","title":"如何在 Kali Linux 上安装 SSH 服务","tag":"201702","desc":""},"relativePath":"201702/20170121 How to install SSH  secure shell  service on Kali Linux.md","filePath":"[post].md"}'),h={name:"201702/20170121 How to install SSH  secure shell  service on Kali Linux.md"};function g(u,s,c,k,b,f){const e=o("Link");return p(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-kali-linux-上安装-ssh-服务" tabindex="-1">如何在 Kali Linux 上安装 SSH 服务 <a class="header-anchor" href="#如何在-kali-linux-上安装-ssh-服务" aria-label="Permalink to “如何在 Kali Linux 上安装 SSH 服务”">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p><strong>目的</strong></p><p>我们的目的是 Kali Linux 上安装 SSH（安全 shell）。</p><p><strong>要求</strong></p><p>你需要有特权访问你的 Kali Linux 安装或者 Live 系统。</p><p><strong>困难程度</strong></p><p>很容易！</p><p><strong>惯例</strong></p><ul><li><code>#</code> - 给定命令需要以 root 用户权限运行或者使用 <code>sudo</code> 命令</li><li><code>$</code> - 给定命令以常规权限用户运行</li></ul><h3 id="指导" tabindex="-1">指导 <a class="header-anchor" href="#指导" aria-label="Permalink to “指导”">​</a></h3><p><strong>安装 SSH</strong></p><p>从终端使用 <code>apt-get</code> 命令安装 SSH 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get update</span></span>
<span class="line"><span># apt-get install ssh</span></span></code></pre></div><p><strong>启用和开始使用 SSH</strong></p><p>为了确保安全 shell 能够使用，在重启系统后使用 <code>systemctl</code> 命令来启用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl enable ssh</span></span></code></pre></div><p>在当前对话执行中使用 SSH:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># service ssh start</span></span></code></pre></div><p><strong>允许 SSH Root 访问</strong></p><p>默认情况下 SSH 不允许以 root 用户登录，因此将会出现下面的错误提示信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Permission denied, please try again.</span></span></code></pre></div><p>为了通过 SSH 进入你的 Kali Linux 系统，你可以有两个不同的选择。第一个选择是创建一个新的非特权用户然后使用它的身份来登录。第二个选择，你可以以 root 用户访问 SSH 。为了实现这件事，需要在SSH 配置文件 <code>/etc/ssh/sshd_config</code> 中插入下面这些行内容或对其进行编辑：</p><p>将</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#PermitRootLogin prohibit-password</span></span></code></pre></div><p>改为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PermitRootLogin yes</span></span></code></pre></div><p><img src="https://linuxconfig.org/images/enable-root-ssh-login-kali-linux.jpg" alt="kali linux enable ssh root access"></p><p>对 <code>/etc/ssh/sshd_config</code> 进行更改以后，需在以 root 用户登录 SSH 前重启 SSH 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># service ssh restart</span></span></code></pre></div><hr>`,31)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux"},{default:a(()=>[...s[0]||(s[0]=[i("https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=i("作者：",-1)),t(e,{href:"https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux"},{default:a(()=>[...s[2]||(s[2]=[i("Lubos Rendek",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),t(e,{href:"https://github.com/ucasFL"},{default:a(()=>[...s[3]||(s[3]=[i("ucasFL",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const C=n(h,[["render",g]]);export{m as __pageData,C as default};
